77:     /**
78:      * @notice Calculates the stalk penalty for a convert. Updates convert capacity used.
79:      */
80:     function prepareStalkPenaltyCalculation(
81:         address inputToken,
82:         address outputToken,
83:         LibConvert.DeltaBStorage memory dbs,
84:         uint256 overallConvertCapacity,
85:         uint256 fromBdv,
86:         uint256[] memory initialLpSupply
87:     ) public returns (uint256) {
88:         dbs.afterOverallDeltaB = LibDeltaB.scaledOverallCurrentDeltaB(initialLpSupply);
89: 
90:         // modify afterInputTokenDeltaB and afterOutputTokenDeltaB to scale using before/after LP amounts
91:         if (LibWell.isWell(inputToken)) {
92:             uint256 i = LibWhitelistedTokens.getIndexFromWhitelistedWellLpTokens(inputToken);
93:             dbs.afterInputTokenDeltaB = LibDeltaB.scaledDeltaB(
94:                 initialLpSupply[i],
95:                 IERC20(inputToken).totalSupply(),
96:                 LibDeltaB.getCurrentDeltaB(inputToken)
97:             );
98:         }
99: 
100:         if (LibWell.isWell(outputToken)) {
101:             uint256 i = LibWhitelistedTokens.getIndexFromWhitelistedWellLpTokens(outputToken);
102:             dbs.afterOutputTokenDeltaB = LibDeltaB.scaledDeltaB(
103:                 initialLpSupply[i],
104:                 IERC20(outputToken).totalSupply(),
105:                 LibDeltaB.getCurrentDeltaB(outputToken)
106:             );
107:         }
108: 
109:         return
110:             LibConvert.applyStalkPenalty(
111:                 dbs,
112:                 fromBdv,
113:                 overallConvertCapacity,
114:                 inputToken,
115:                 outputToken
116:             );
117:     }
