119:     /**
120:      * @param calls The advanced farm calls to execute.
121:      */
122:     function executeAdvancedFarmCalls(AdvancedFarmCall[] calldata calls) internal {
123:         bytes[] memory results;
124:         results = new bytes[](calls.length);
125:         for (uint256 i = 0; i < calls.length; ++i) {
126:             require(calls[i].callData.length != 0, "Convert: empty AdvancedFarmCall");
127:             results[i] = LibFarm._advancedFarm(calls[i], results);
128:         }
129:     }
