131:     /**
132:      * @notice Determines input token amount left in pipeline and returns to Beanstalk
133:      * @param tokenOut The token to pull out of pipeline
134:      */
135:     function transferTokensFromPipeline(address tokenOut) internal returns (uint256 amountOut) {
136:         amountOut = IERC20(tokenOut).balanceOf(C.PIPELINE);
137:         require(amountOut > 0, "Convert: No output tokens left in pipeline");
138: 
139:         PipeCall memory p;
140:         p.target = address(tokenOut);
141:         p.data = abi.encodeWithSelector(IERC20.transfer.selector, address(this), amountOut);
142:         IPipeline(C.PIPELINE).pipe(p);
143:     }
