145:     function populatePipelineConvertData(
146:         address fromToken,
147:         address toToken
148:     ) internal view returns (PipelineConvertData memory pipeData) {
149:         pipeData.deltaB.beforeOverallDeltaB = LibDeltaB.overallCurrentDeltaB();
150:         pipeData.deltaB.beforeInputTokenDeltaB = LibDeltaB.getCurrentDeltaB(fromToken);
151:         pipeData.deltaB.beforeOutputTokenDeltaB = LibDeltaB.getCurrentDeltaB(toToken);
152:         pipeData.initialLpSupply = LibDeltaB.getLpSupply();
153:     }
