165:             kind == LibConvertData.ConvertKind.BEANS_TO_WELL_LP ||
166:             kind == LibConvertData.ConvertKind.WELL_LP_TO_BEANS
167:         ) {
168:             if (kind == LibConvertData.ConvertKind.BEANS_TO_WELL_LP) {
169:                 (, , toToken) = convertData.convertWithAddress();
170:                 fromToken = C.BEAN;
171:                 require(LibWell.isWell(toToken), "Convert: Invalid Well");
172:             } else {
173:                 (, , fromToken) = convertData.convertWithAddress();
174:                 toToken = C.BEAN;
175:                 require(LibWell.isWell(fromToken), "Convert: Invalid Well");
176:             }
177: 
178:             pipeData = populatePipelineConvertData(fromToken, toToken);
179:         }
180:     }
